		V = $.name;
		if(v[v.length-1]!=V&&!/^\s*$/.test(V)){
				v.push(V)
				list.push({
						name: '['+V+']',
						volume: true
					})
			}

$.bookChapters.map($=>{
		return list.push({
				name: $.name,
